drop table if exists public.venue_amenities, public.artist_genres, public.venues, public.artists, public.availability, public.events, public.supplier_packages, public.supplier_profiles, public.supplier_types, public.cities, public.regions, public.amenities, public.genres, public.event_types, public.profiles cascade;
drop function if exists public.blocked_dates(uuid) cascade;
drop function if exists public.guard_event_insert() cascade;
drop function if exists public.guard_supplier_status() cascade;
drop function if exists public.grant_supplier_role() cascade;
drop function if exists public.owns_supplier(uuid) cascade;
drop type if exists public.event_status cascade;
drop type if exists public.supplier_status cascade;

create table public.regions (id uuid primary key default gen_random_uuid(), name_he text not null, name_ar text not null, sort_order integer not null default 0, created_at timestamptz default now(), updated_at timestamptz default now());
create table public.cities (id uuid primary key default gen_random_uuid(), region_id uuid not null references public.regions(id), name_he text not null, name_ar text not null, sort_order integer not null default 0, created_at timestamptz default now(), updated_at timestamptz default now());
create table public.supplier_types (id uuid primary key default gen_random_uuid(), code text not null unique, name_he text not null, name_ar text not null, icon text, sort_order integer not null default 0, is_active boolean not null default true, created_at timestamptz default now(), updated_at timestamptz default now());
create table public.service_categories (id uuid primary key default gen_random_uuid(), supplier_type_id uuid not null references public.supplier_types(id), code text not null, name_he text not null, name_ar text not null, sort_order integer not null default 0, created_at timestamptz default now(), updated_at timestamptz default now());
create table public.amenities (id uuid primary key default gen_random_uuid(), code text not null, name_he text not null, name_ar text not null, icon text, created_at timestamptz default now(), updated_at timestamptz default now());
create table public.genres (id uuid primary key default gen_random_uuid(), code text not null, name_he text not null, name_ar text not null, created_at timestamptz default now(), updated_at timestamptz default now());
create table public.event_types (id uuid primary key default gen_random_uuid(), code text not null, name_he text not null, name_ar text not null, icon text, sort_order integer not null default 0, created_at timestamptz default now(), updated_at timestamptz default now());
create table public.profiles (id uuid primary key, email text not null, full_name text, phone text, avatar_url text, role text not null default 'customer', preferred_language text not null default 'he', created_at timestamptz default now(), updated_at timestamptz default now());
create table public.customer_profiles (id uuid primary key default gen_random_uuid(), user_id uuid not null, default_event_type_id uuid references public.event_types(id), created_at timestamptz default now(), updated_at timestamptz default now());
create table public.supplier_profiles (id uuid primary key default gen_random_uuid(), user_id uuid, supplier_type_id uuid not null references public.supplier_types(id), business_name_he text not null, business_name_ar text, description_he text, description_ar text, phone text, email text, website text, instagram text, facebook text, tiktok text, youtube text, city_id uuid references public.cities(id), address text, rating numeric not null default 0, review_count integer not null default 0, is_verified boolean not null default false, is_featured boolean not null default false, verification_status text not null default 'pending', min_price numeric, max_price numeric, starting_price numeric, total_bookings integer not null default 0, created_at timestamptz default now(), updated_at timestamptz default now());
create table public.venues (id uuid primary key default gen_random_uuid(), supplier_id uuid not null references public.supplier_profiles(id) on delete cascade, min_guests integer not null default 0, max_guests integer not null default 0, price_per_guest numeric not null default 0, venue_type text not null default 'indoor', has_parking boolean not null default false, has_accessibility boolean not null default false, is_kosher boolean not null default false, kosher_certificate text, latitude numeric, longitude numeric, created_at timestamptz default now(), updated_at timestamptz default now());
create table public.artists (id uuid primary key default gen_random_uuid(), supplier_id uuid not null references public.supplier_profiles(id) on delete cascade, performance_duration_min integer not null default 120, languages_he text[], languages_ar text[], created_at timestamptz default now(), updated_at timestamptz default now());
create table public.venue_amenities (id uuid primary key default gen_random_uuid(), venue_id uuid not null references public.venues(id) on delete cascade, amenity_id uuid not null references public.amenities(id) on delete cascade);
create table public.artist_genres (id uuid primary key default gen_random_uuid(), artist_id uuid not null references public.artists(id) on delete cascade, genre_id uuid not null references public.genres(id) on delete cascade);
create table public.supplier_packages (id uuid primary key default gen_random_uuid(), supplier_id uuid not null references public.supplier_profiles(id) on delete cascade, name_he text not null, name_ar text, description_he text, description_ar text, price numeric not null default 0, duration_hours integer, included_services text[], created_at timestamptz default now(), updated_at timestamptz default now());
create table public.media (id uuid primary key default gen_random_uuid(), supplier_id uuid not null references public.supplier_profiles(id) on delete cascade, url text not null, thumbnail_url text, media_type text not null default 'photo', sort_order integer not null default 0, is_cover boolean not null default false, created_at timestamptz default now());
create table public.supplier_service_areas (id uuid primary key default gen_random_uuid(), supplier_id uuid not null references public.supplier_profiles(id) on delete cascade, city_id uuid references public.cities(id), region_id uuid references public.regions(id), created_at timestamptz default now());
create table public.availability (id uuid primary key default gen_random_uuid(), supplier_id uuid not null references public.supplier_profiles(id) on delete cascade, date date not null, status text not null default 'available', note text, created_at timestamptz default now(), updated_at timestamptz default now());
create table public.events (id uuid primary key default gen_random_uuid(), user_id uuid not null default auth.uid(), event_name text not null, event_type_id uuid references public.event_types(id), event_date date not null, city_id uuid references public.cities(id), location text, expected_guests integer not null default 0, total_budget numeric not null default 0, notes text, is_active boolean not null default true, created_at timestamptz default now(), updated_at timestamptz default now());
create table public.booking_requests (id uuid primary key default gen_random_uuid(), customer_id uuid not null default auth.uid(), supplier_id uuid not null references public.supplier_profiles(id) on delete cascade, event_id uuid references public.events(id) on delete set null, event_date date not null, city_id uuid references public.cities(id), guest_count integer, budget numeric, message text, status text not null default 'requested', created_at timestamptz default now(), updated_at timestamptz default now());
create table public.booking_status_history (id uuid primary key default gen_random_uuid(), booking_request_id uuid not null references public.booking_requests(id) on delete cascade, previous_status text, new_status text not null, changed_by uuid, note text, created_at timestamptz default now());
create table public.quotations (id uuid primary key default gen_random_uuid(), booking_request_id uuid not null references public.booking_requests(id) on delete cascade, supplier_id uuid not null references public.supplier_profiles(id), customer_id uuid not null, description text, total_amount numeric not null default 0, required_deposit numeric not null default 0, expiration_date date, status text not null default 'sent', created_at timestamptz default now(), updated_at timestamptz default now());
create table public.quotation_items (id uuid primary key default gen_random_uuid(), quotation_id uuid not null references public.quotations(id) on delete cascade, description text not null, quantity integer not null default 1, unit_price numeric not null default 0, total_price numeric not null default 0, created_at timestamptz default now());
create table public.payments (id uuid primary key default gen_random_uuid(), booking_request_id uuid not null references public.booking_requests(id), customer_id uuid not null, supplier_id uuid not null references public.supplier_profiles(id), payment_type text not null, amount numeric not null default 0, status text not null default 'pending', payment_method text, created_at timestamptz default now(), updated_at timestamptz default now());
create table public.payment_transactions (id uuid primary key default gen_random_uuid(), payment_id uuid not null references public.payments(id) on delete cascade, provider text, provider_transaction_id text, amount numeric not null default 0, status text not null default 'pending', metadata jsonb, created_at timestamptz default now());
create table public.commission_records (id uuid primary key default gen_random_uuid(), booking_request_id uuid not null references public.booking_requests(id), payment_id uuid references public.payments(id), commission_rate numeric not null default 0, commission_amount numeric not null default 0, created_at timestamptz default now());
create table public.reviews (id uuid primary key default gen_random_uuid(), supplier_id uuid not null references public.supplier_profiles(id) on delete cascade, customer_id uuid default auth.uid(), booking_request_id uuid references public.booking_requests(id), rating integer not null, comment text, is_verified boolean not null default false, customer_name text, created_at timestamptz default now(), updated_at timestamptz default now());
create table public.favorites (id uuid primary key default gen_random_uuid(), user_id uuid not null default auth.uid(), supplier_id uuid not null references public.supplier_profiles(id) on delete cascade, created_at timestamptz default now());
create table public.conversations (id uuid primary key default gen_random_uuid(), customer_id uuid not null, supplier_id uuid not null references public.supplier_profiles(id) on delete cascade, booking_request_id uuid references public.booking_requests(id), last_message_at timestamptz default now(), created_at timestamptz default now());
create table public.messages (id uuid primary key default gen_random_uuid(), conversation_id uuid not null references public.conversations(id) on delete cascade, sender_id uuid not null, message_text text not null, is_read boolean not null default false, created_at timestamptz default now());
create table public.notifications (id uuid primary key default gen_random_uuid(), user_id uuid not null default auth.uid(), type text not null, title_he text, title_ar text, body_he text, body_ar text, data jsonb, is_read boolean not null default false, created_at timestamptz default now());

-- tables the dashboards don't use yet: owner/admin only for now
grant select, insert, update, delete on public.customer_profiles, public.quotations, public.quotation_items, public.payments, public.payment_transactions, public.commission_records, public.reviews, public.favorites, public.conversations, public.messages, public.notifications to authenticated;
grant all on public.customer_profiles, public.quotations, public.quotation_items, public.payments, public.payment_transactions, public.commission_records, public.reviews, public.favorites, public.conversations, public.messages, public.notifications to service_role;
alter table public.customer_profiles enable row level security;
alter table public.quotations enable row level security;
alter table public.quotation_items enable row level security;
alter table public.payments enable row level security;
alter table public.payment_transactions enable row level security;
alter table public.commission_records enable row level security;
alter table public.reviews enable row level security;
alter table public.favorites enable row level security;
alter table public.conversations enable row level security;
alter table public.messages enable row level security;
alter table public.notifications enable row level security;
create policy "own customer_profiles" on public.customer_profiles for all to authenticated using (user_id = auth.uid() or public.has_role(auth.uid(),'admin')) with check (user_id = auth.uid() or public.has_role(auth.uid(),'admin'));
create policy "own favorites" on public.favorites for all to authenticated using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy "own notifications" on public.notifications for all to authenticated using (user_id = auth.uid() or public.has_role(auth.uid(),'admin')) with check (user_id = auth.uid() or public.has_role(auth.uid(),'admin'));
create policy "read reviews" on public.reviews for select using (true);
grant select on public.reviews to anon;
create policy "write own reviews" on public.reviews for insert to authenticated with check (customer_id = auth.uid());
create policy "admin reviews" on public.reviews for all to authenticated using (public.has_role(auth.uid(),'admin')) with check (public.has_role(auth.uid(),'admin'));
create policy "admin quotations" on public.quotations for all to authenticated using (customer_id = auth.uid() or public.has_role(auth.uid(),'admin')) with check (public.has_role(auth.uid(),'admin'));
create policy "admin quotation_items" on public.quotation_items for all to authenticated using (public.has_role(auth.uid(),'admin')) with check (public.has_role(auth.uid(),'admin'));
create policy "admin payments" on public.payments for all to authenticated using (customer_id = auth.uid() or public.has_role(auth.uid(),'admin')) with check (public.has_role(auth.uid(),'admin'));
create policy "admin payment_transactions" on public.payment_transactions for all to authenticated using (public.has_role(auth.uid(),'admin')) with check (public.has_role(auth.uid(),'admin'));
create policy "admin commission_records" on public.commission_records for all to authenticated using (public.has_role(auth.uid(),'admin')) with check (public.has_role(auth.uid(),'admin'));
create policy "own conversations" on public.conversations for all to authenticated using (customer_id = auth.uid() or public.has_role(auth.uid(),'admin')) with check (customer_id = auth.uid() or public.has_role(auth.uid(),'admin'));
create policy "admin messages" on public.messages for all to authenticated using (sender_id = auth.uid() or public.has_role(auth.uid(),'admin')) with check (sender_id = auth.uid());

create or replace function public.handle_new_user()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  insert into public.profiles (id, full_name, email) values (new.id, new.raw_user_meta_data->>'full_name', coalesce(new.email, ''))
  on conflict (id) do nothing;
  return new;
end $$;